            if color == 0 or (r, c) in seen:
                continue
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            objects.append((color, cells))

    # Pack the rigid objects against the right edge, placing rightmost ones first.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        shift = 0
        while True:
            nxt = shift + 1
            if any(c + nxt >= w or out[r][c+nxt] != 0 for r, c in cells):
                break
            shift = nxt
        for r, c in cells:
            out[r][c+shift] = color
    return out
